"""Create a Russian review report from actual saved-model verification."""
import argparse
import json
from pathlib import Path


def main():
    parser=argparse.ArgumentParser(description=__doc__)
    parser.add_argument('blend',type=Path)
    args=parser.parse_args();source=args.blend.resolve(strict=True)
    audit=json.loads(source.with_suffix('.report.json').read_text(encoding='utf-8'))
    check=json.loads(source.with_suffix('.reopen-verification.json').read_text(encoding='utf-8'))
    vent=audit['ventilation']
    lines=['# Вентиляция здания 5800–1.3: результат и замечания','',
           'Назначение: общий вид здания и его инженерных сетей. Геометрия добавлена по исходным DWG через AutoCAD 2014 COM и MCP; DWG не конвертировались. Это обзорная модель с явно указанными допущениями. Инженерная координация не завершена.','',
           f"Модель: `{source}`.",'',
           '## Состав','',
           'Системы: П1/В1, В2, В3, В4, В5, ВЕ1, ВЕ2. Два этажа, стояки и выходы на кровлю.','',
           '| Категория | Число mesh-объектов |','|---|---:|']
    lines.extend(f'| {category} | {count} |' for category,count in vent['counts'].items())
    lines.extend(['',f"Всего добавлено {check['ventilation_objects']} объектов, в общей модели {check['objects']}. Фасонные части могут состоять из нескольких замкнутых оболочек; число mesh-объектов не является количеством изделий.",'',
                  '28 квадратных и 13 круглых воздухораспределителей, 5 решёток/воздухозаборных устройств; 28 гибких подключений. Корпуса ПВУ, двух крышных и одного канального вентилятора представлены упрощённо.','',
                  '## Источники и воспроизводимость','',
                  'Использованы основные листы ОВ-011/012/013/014 REV.0, общие указания ОВ-002 REV.0 и спецификация ОВ.СО REV.1. Геометрия повторяющихся планов прочитана из ОВ-011; контрольные привязки соответствующих листов сопоставлены через COM. Архивные варианты и библиотека неустановленных изделий не включались.','',
                  'Передано 11 263 записи выбранного участка DWG и дополнительно прочитана отметка +3.150, ранее пропущенная выборкой из-за отсутствовавшего bbox. Проверено 4 788 геометрических ссылок с допуском 0,25 мм. Скрытые варианты динамических блоков исключены явно. MLeader используется как текст и читаемые выноски; MLine — как базовая линия маршрута, без заявления о полном восстановлении стиля.','',
                  'Геометрия остаётся во встроенном COM-пакете BLEND. PNG — контрольные изображения; GLB — производная проверенного BLEND для браузера. Промежуточного экспорта DWG не было.','',
                  '## Фактическая проверка','',
                  f"- Повторное открытие в Blender {check['blender_version']}: {'пройдено' if check['passed'] else 'не пройдено'}.",
                  f"- Проверены координаты и замкнутость {check['objects']} сохранённых mesh-объектов.",
                  f"- Независимо от журнала ожидаемых вершин сверены {len(check['source_derived_body_checks'])} прямых участков с COM-контурами, номинальными сечениями и текстами отметок.",
                  f"- Максимальная численная ошибка координат: {check['max_coordinate_error_mm']:.6f} мм при допуске 0,25 мм.",
                  f"- Максимальная независимая ошибка плановых размеров/отметок/сечений: {max(max(c['xy_error_mm'],c['elevation_error_mm'],c['section_error_mm']) for c in check['source_derived_body_checks']):.6f} мм. Это численная сверка принятых связей с выносками, а не подтверждение их семантики.",
                  f"- Размеры корпуса ПВУ 961 × 3378 × 986 мм: ошибка {check['ahu_specification_size_error_mm']:.6f} мм.",
                  '- Все 1 121 исходных объектов архитектуры сохранены; изменение их вершин — 0 мм.',
                  '- Совпадение чисел с источником не подтверждает правильность семантического назначения каждого элемента.',
                  '', '## Принятые допущения','',
                  '| Параметр | Принято | Статус |','|---|---|---|',
                  '| Квадратные диффузоры | Низ +2.750 м относительно чистого пола каждого этажа; 30 мм толщина | Не подтверждено общей отметкой потолка |',
                  '| Высота прямоугольных участков | По ближайшей выноске с той же плановой шириной | Связь выноски с участком выбрана эвристически; требует проверки |',
                  '| Отметки | Круглые — по оси, прямоугольные — по нижней грани | Интерпретация обозначений схемы |',
                  '| Фасонные части | Плановые очертания и соседние сечения; часть соединительных переходов достроена | Обзорное приближение |',
                  '| Гибкие участки | Записанная линия MLine в XY и переход к принятой высоте терминала | Смещение стиля MLine и пространственный профиль не подтверждены |',
                  '| ПВУ | Габарит VVS021 из более поздней спецификации; центр по плану AVS012 | Обнаружено расхождение ревизий, положение портов предварительное |',
                  '| Подвес ПВУ | Низ +2.707, верх +3.693 м, относительно интерфейсов воздуховодов | Не подтверждено монтажным размером |',
                  '| Крышные вентиляторы | Плановый габарит 580 × 580 мм; высота корпуса 330 мм | Высота упрощена |',
                  '| Естественные вытяжки/В5 | Условная отметка окончания +8.570 м там, где схема указывает «отм. кровли» | Требует высотной координации |',
                  '| Изоляция | 6 мм на построенных приточных участках, 40 мм на наружных вытяжных стояках | Узлы и часть фасонных поверхностей не утеплены полностью |',
                  '| Изделия | Без внутренних деталей, подвесов, крепежа и полного набора клапанов | Не для спецификации изготовления |',
                  '', '## Пересечения с конструкциями','',
                  f"Найдено {len(check['clashes'])} пар пересекающихся поверхностей. Это кандидаты на коллизии, а не подтверждённое число проектных ошибок: проходы стен и плит в обзорной архитектурной модели не вырезались.",'',
                  'Особое замечание: стояк В5 пересекает две балки модели (`Overview/0035`, `Overview/0056`). Нужна сверка ОВ и КЖ. Трасса сохранена в плановом положении исходного ОВ. Для общего вида это не блокирует просмотр; для монтажной модели требуется решение проектировщика.','',
                  '| Вентиляционный объект | Конструкция | Категория |','|---|---|---|'])
    lines.extend(f"| `{c['element_id']}` | `{c['building_element_id']}` | {c['building_category']} |" for c in check['clashes'])
    lines.extend(['','## Точки сопряжения для уточнения','',
                  f"Автоматическая проверка обнаружила {len(check['open_measured_body_ports'])} концов прямых участков без подтверждённого контакта с соседней оболочкой в пределах 5 мм. В это число входят незавершённые узлы и неоднозначности сечений/уровней. Ближайший объект не обязательно принадлежит той же системе; автоматически соединять такие пары нельзя.",'',
                  '| Участок | Порт | X / Y / Z, мм | Расстояние до ближайшей оболочки, мм |','|---|---:|---|---:|'])
    for p in check['open_measured_body_ports']:
        position=' / '.join(f'{v:.1f}' for v in p['point_mm'])
        gap='не найдено' if p['nearest_gap_mm'] is None else f"{p['nearest_gap_mm']:.1f}"
        lines.append(f"| `{p['element_id']}` | {p['port']} | {position} | {gap} |")
    lines.extend(['','## Как посмотреть','',
                  'Локально: http://127.0.0.1:8765/. Нажмите «Только вентиляция», затем выберите систему в выпадающем списке. Горизонтальный разрез на +4.00 м показывает нижний этаж. Для совместного просмотра верните «Показать всё» и отключите кровлю/верхнюю плиту.','',
                  'В Blender откройте `erdaut_with_ventilation.blend`, коллекция `Engineering - Ventilation`; внутри — системы и этажи.','',
                  '## Файлы контроля','',
                  '- `erdaut_with_ventilation.report.json` — элементы, источники, принятые правила и размерные проверки.',
                  '- `erdaut_with_ventilation.reopen-verification.json` — независимое повторное открытие, 39 пересечений и 15 точек сопряжения.',
                  '- `evidence/ventilation/source-preservation-after.json` — 363 файла защищённой папки: добавлений, удалений и изменений нет; 18 исходных DWG ОВ и их копии совпадают по SHA-256.',
                  '- `erdaut_with_ventilation.exterior.png`, `.networks.png`, `.ground.png`, `.upper.png`, `.roof.png` — пять контрольных видов.',
                  '', 'Для следующего уровня детализации нужны согласованное положение стояка В5 относительно балок, проверка 15 сопряжений, отметки потолков и монтажные данные выбранного оборудования.'])
    target=source.with_suffix('.summary.ru.md');target.write_text('\n'.join(lines)+'\n',encoding='utf-8')
    print(target)


if __name__=='__main__':main()
